/* Color palette: #2b2d42 (dark), #8d99ae (muted), #edf2f4 (light), #ef233c (accent red), #4caf50 (green) */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  font-size: 16px;
  background: #2b2d42;
  color: #edf2f4;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  padding: 16px;
}

.game-card {
  background: #3a3d5c;
  border-radius: 24px;
  padding: 32px 24px;
  max-width: 480px;
  width: 100%;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 2rem;
  margin-bottom: 24px;
  color: #edf2f4;
  letter-spacing: 1px;
}

.pet-container {
  display: flex;
  justify-content: center;
  margin-bottom: 16px;
}

.pet {
  width: 128px;
  height: 128px;
  background: #ef233c;
  border-radius: 16px;
  position: relative;
  box-shadow: inset -8px -8px 0 rgba(0, 0, 0, 0.15);
  transition: transform 0.2s;
}

.pet:hover {
  transform: scale(1.05);
}

.pet-face {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 80px;
  height: 60px;
}

.pet-eye {
  width: 16px;
  height: 16px;
  background: #2b2d42;
  border-radius: 4px;
  position: absolute;
  top: 10px;
}

.pet-eye.left {
  left: 10px;
}

.pet-eye.right {
  right: 10px;
}

.pet-mouth {
  width: 32px;
  height: 12px;
  background: #2b2d42;
  border-radius: 0 0 16px 16px;
  position: absolute;
  bottom: 8px;
  left: 50%;
  transform: translateX(-50%);
}

.mood {
  font-size: 1.25rem;
  margin-bottom: 24px;
  font-weight: 600;
  color: #8d99ae;
}

.stats {
  display: flex;
  flex-direction: column;
  gap: 16px;
  margin-bottom: 32px;
}

.stat {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;
}

.stat-label {
  font-size: 0.9rem;
  font-weight: 600;
  color: #8d99ae;
  text-transform: uppercase;
  letter-spacing: 1px;
}

.stat-bar {
  width: 100%;
  height: 20px;
  background: #2b2d42;
  border-radius: 10px;
  overflow: hidden;
}

.stat-fill {
  height: 100%;
  border-radius: 10px;
  transition: width 0.3s ease;
}

.stat-fill.hunger {
  background: #ef233c;
}

.stat-fill.happiness {
  background: #4caf50;
}

.stat-fill.energy {
  background: #8d99ae;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
  flex-wrap: wrap;
}

.btn {
  font-family: inherit;
  font-size: 1.1rem;
  font-weight: 700;
  padding: 12px 24px;
  border: none;
  border-radius: 12px;
  cursor: pointer;
  transition: background 0.2s, transform 0.1s;
  color: #edf2f4;
  background: #8d99ae;
  min-width: 100px;
}

.btn:hover {
  background: #a0aec0;
}

.btn:focus-visible {
  outline: 3px solid #edf2f4;
  outline-offset: 2px;
}

.btn:active {
  transform: scale(0.95);
}

.btn.feed {
  background: #ef233c;
}

.btn.feed:hover {
  background: #ff4d6d;
}

.btn.play {
  background: #4caf50;
}

.btn.play:hover {
  background: #66bb6a;
}

.btn.sleep {
  background: #8d99ae;
}

.btn.sleep:hover {
  background: #a0aec0;
}

@media (max-width: 400px) {
  .game-card {
    padding: 24px 16px;
  }
  .btn {
    padding: 10px 16px;
    font-size: 1rem;
    min-width: 80px;
  }
}

// Pixel Virtual Pet logic
const state = {
  hunger: 50,
  happiness: 50,
  energy: 50
};

const hungerBar = document.getElementById('hungerBar');
const happinessBar = document.getElementById('happinessBar');
const energyBar = document.getElementById('energyBar');
const moodText = document.getElementById('mood');

function clamp(value) {
  return Math.max(0, Math.min(100, value));
}

function updateBars() {
  hungerBar.style.width = state.hunger + '%';
  happinessBar.style.width = state.happiness + '%';
  energyBar.style.width = state.energy + '%';
}

function updateMood() {
  const avg = (state.hunger + state.happiness + state.energy) / 3;
  let mood;
  if (avg >= 70) mood = 'Happy';
  else if (avg >= 40) mood = 'Okay';
  else mood = 'Sad';
  moodText.textContent = 'Mood: ' + mood;
}

function feed() {
  state.hunger = clamp(state.hunger + 20);
  state.energy = clamp(state.energy - 5);
  updateBars();
  updateMood();
}

function play() {
  state.happiness = clamp(state.happiness + 20);
  state.energy = clamp(state.energy - 15);
  state.hunger = clamp(state.hunger - 10);
  updateBars();
  updateMood();
}

function sleep() {
  state.energy = clamp(state.energy + 30);
  state.hunger = clamp(state.hunger - 10);
  updateBars();
  updateMood();
}

document.getElementById('feedBtn').addEventListener('click', feed);
document.getElementById('playBtn').addEventListener('click', play);
document.getElementById('sleepBtn').addEventListener('click', sleep);

// Initial update
updateBars();
updateMood();
